userEnteredValue.formulaValue:
=SUM(
  FILTER(
    ARRAYFORMULA(
      IN_LOAN_PARAM_VALUES_BY_LOAN("totals", "total in loans received") +
      OUT_LOAN_PARAM_VALUES_BY_LOAN("totals", "total out loan repayments received") +
      REVENUE_PARAM_VALUES("total revenue")
    ),
    ARRAYFORMULA(YEAR(R_MONTHS)) = BUDGET_VALUE("_year")
  )
)

=IFNA(
  SUM(
    FILTER(
      CASH_FLOW_PARAM_VALUES("company tax"),
      IFERROR(YEAR(R_MONTHS) = BUDGET_VALUE("_year"), FALSE),
      R_MONTHS < MONTH_START(TODAY())
    )
  ),
  0
)

